import java.util.*;

class Solution {
  public double[] outerTrees(int[][] trees) {
    // Welzl-style incremental minimum enclosing circle (expected linear after shuffling)
    List<int[]> pts = new ArrayList<>(Arrays.asList(trees));
    Collections.shuffle(pts, new Random(7));
    double[] c = {pts.get(0)[0], pts.get(0)[1], 0};
    for (int i = 1; i < pts.size(); i++) {
      if (inside(c, pts.get(i))) continue;
      c = new double[] {pts.get(i)[0], pts.get(i)[1], 0};
      for (int j = 0; j < i; j++) {
        if (inside(c, pts.get(j))) continue;
        c = fromTwo(pts.get(i), pts.get(j));
        for (int k = 0; k < j; k++) if (!inside(c, pts.get(k))) c = fromThree(pts.get(i), pts.get(j), pts.get(k));
      }
    }
    return c;
  }

  private boolean inside(double[] c, int[] p) {
    return Math.hypot(p[0] - c[0], p[1] - c[1]) <= c[2] + 1e-7;
  }

  private double[] fromTwo(int[] a, int[] b) {
    double x = (a[0] + b[0]) / 2.0, y = (a[1] + b[1]) / 2.0;
    return new double[] {x, y, Math.hypot(a[0] - x, a[1] - y)};
  }

  private double[] fromThree(int[] a, int[] b, int[] c) {
    double bx = b[0] - a[0], by = b[1] - a[1], cx = c[0] - a[0], cy = c[1] - a[1];
    double d = 2 * (bx * cy - by * cx);
    if (Math.abs(d) < 1e-12) { // collinear: the circle on the farthest pair
      double[] best = fromTwo(a, b);
      for (double[] cand : new double[][] {fromTwo(a, c), fromTwo(b, c)}) if (cand[2] > best[2]) best = cand;
      return best;
    }
    double ux = (cy * (bx * bx + by * by) - by * (cx * cx + cy * cy)) / d;
    double uy = (bx * (cx * cx + cy * cy) - cx * (bx * bx + by * by)) / d;
    return new double[] {ux + a[0], uy + a[1], Math.hypot(ux, uy)};
  }
}
